package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string // PIC X(2) @0 len=2
	BrAcct   string // PIC X(4) @2 len=4
	BrType   string // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsFirstFlag string // PIC X len=1 = "Y"
var WsPrevBranch string // PIC X(2) len=2 = SPACES
var WsPrevAcct string // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 // PIC 99 len=2 = 0
var WsAmtEd string // PIC ZZ,ZZ9.99 len=9
var WsBalEd string // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var curRec LedgerRec
var inputLines []string
var inputIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseAmt(field string) decimal.Decimal {
	// field length 7, digits only, implied 2 decimals
	// treat spaces as 0, non-digits as 0
	var v int64 = 0
	for i := 0; i < len(field); i++ {
		c := field[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		v = v*10 + d
	}
	return decimal.New(v, -2)
}

func parseLine(line string) LedgerRec {
	s := padRight(line, 14)
	if len(s) > 14 {
		s = s[:14]
	}
	r := LedgerRec{}
	r.BrBranch = s[0:2]
	r.BrAcct = s[2:6]
	r.BrType = s[6:7]
	r.BrAmt = parseAmt(s[7:14])
	return r
}

// storage truncation: keep low-order digits, truncate to scale
func storeSigned(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := v.Truncate(scale)
	// modulus = 10^(intDigits+scale)
	modExp := int64(intDigits) + int64(scale)
	mod := decimal.NewFromInt(1)
	ten := decimal.NewFromInt(10)
	for i := int64(0); i < modExp; i++ {
		mod = mod.Mul(ten)
	}
	neg := t.IsNegative()
	absScaled := t.Abs().Shift(scale)
	// absScaled should be integer already
	absScaled = absScaled.Truncate(0)
	rem := absScaled.Mod(mod)
	var scaled decimal.Decimal
	if neg {
		scaled = rem.Neg()
	} else {
		scaled = rem
	}
	// zero should be positive
	if scaled.IsZero() {
		return decimal.NewFromInt(0)
	}
	return scaled.Shift(-scale)
}

func storeBal(v decimal.Decimal) decimal.Decimal {
	return storeSigned(v, 7, 2)
}
func storeTot(v decimal.Decimal) decimal.Decimal {
	return storeSigned(v, 9, 2)
}

// generic numeric-edited formatting
func formatEdited(v decimal.Decimal, picture string) string {
	// find scale = digits after '.'
	scale := int32(0)
	if idx := strings.Index(picture, "."); idx >= 0 {
		scale = int32(len(picture) - idx - 1)
		// count only 9s after dot (should be all 9)
	}
	hasSign := strings.HasPrefix(picture, "-") || strings.HasPrefix(picture, "+")
	// collect integer placeholder types in order
	// integer part = before '.'
	intPic := picture
	if idx := strings.Index(picture, "."); idx >= 0 {
		intPic = picture[:idx]
	}
	// remove sign char from intPic for placeholder counting
	if hasSign {
		intPic = intPic[1:]
	}
	// digit placeholder count
	nInt := 0
	for i := 0; i < len(intPic); i++ {
		if intPic[i] == 'Z' || intPic[i] == '9' {
			nInt++
		}
	}
	// fractional placeholders count = scale
	t := v.Truncate(scale)
	neg := t.IsNegative()
	absV := t.Abs()
	scaledAbs := absV.Shift(scale).Truncate(0)
	s := scaledAbs.String()
	// s may contain decimal point if not integer? but truncated integer so no
	// remove possible minus (abs so no) and exponent? assume plain
	if idx := strings.IndexAny(s, ".eE"); idx >= 0 {
		// fallback: use StringFixed
		s = absV.StringFixed(scale)
		s = strings.Replace(s, ".", "", 1)
		s = strings.Replace(s, "-", "", 1)
		// now s is digits
	} else {
		// s is integer digits
	}
	// s currently is scaled integer digits (no leading zeros except "0")
	// ensure only digits
	ds := ""
	for i := 0; i < len(s); i++ {
		if s[i] >= '0' && s[i] <= '9' {
			ds += string(s[i])
		}
	}
	if ds == "" {
		ds = "0"
	}
	// split frac / int
	var fracStr string
	var intStr string
	if int64(len(ds)) <= int64(scale) {
		// pad left with zeros to scale+1
		need := int(scale) + 1 - len(ds)
		ds = strings.Repeat("0", need) + ds
		fracStr = ds[len(ds)-int(scale):]
		intStr = ds[:len(ds)-int(scale)]
	} else {
		if scale == 0 {
			fracStr = ""
			intStr = ds
		} else {
			fracStr = ds[len(ds)-int(scale):]
			intStr = ds[:len(ds)-int(scale)]
		}
	}
	// strip leading zeros of intStr, keep one
	intStr = strings.TrimLeft(intStr, "0")
	if intStr == "" {
		intStr = "0"
	}
	// overflow: keep low-order nInt digits
	if len(intStr) > nInt {
		intStr = intStr[len(intStr)-nInt:]
	}
	// build digit array D length nInt, zero-padded left
	D := make([]byte, nInt)
	padded := strings.Repeat("0", nInt-len(intStr)) + intStr
	for i := 0; i < nInt; i++ {
		D[i] = padded[i]
	}
	// find first nonzero
	firstNZ := nInt // none
	for i := 0; i < nInt; i++ {
		if D[i] != '0' {
			firstNZ = i
			break
		}
	}
	// build integer part output
	// iterate over intPic chars, consuming D
	var intOut strings.Builder
	di := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			d := D[di]
			if c == 'Z' && di < firstNZ {
				intOut.WriteByte(' ')
			} else {
				intOut.WriteByte(d)
			}
			di++
		} else if c == ',' {
			// suppressed if all digits to left are suppressed
			// i.e., number of digit positions consumed so far <= firstNZ and those were all Z?
			// Equivalent: if di <= firstNZ then space else comma
			// But need to consider that digits left may include '9'? '9' never suppressed.
			// General: check if any non-suppressed digit to the left
			suppressed := true
			// look at digits left of comma: if any digit index < di that is not suppressed, then not suppressed
			for k := 0; k < di; k++ {
				// was position k suppressed? need placeholder type; simplify: if k >= firstNZ then not suppressed
				if k >= firstNZ {
					suppressed = false
					break
				}
				// if k < firstNZ but placeholder was '9', it would have printed 0 -> not suppressed
				// find placeholder for k: need mapping; approximate by checking intPic placeholders
				// To be precise, recompute: placeholder of digit k
			}
			// More precise: determine placeholder chars for digits
			// Build placeholder list
			_ = suppressed
			if di <= firstNZ {
				// all digits left are leading zeros; but if any left placeholder is '9', it printed 0 so comma should show?
				// In our pictures, '9' is only last position, which is always right of commas, so di<=firstNZ implies suppressed.
				intOut.WriteByte(' ')
			} else {
				intOut.WriteByte(',')
			}
		} else {
			intOut.WriteByte(c)
		}
	}
	var out strings.Builder
	if hasSign {
		if neg {
			out.WriteByte('-')
		} else {
			out.WriteByte(' ')
		}
	}
	out.WriteString(intOut.String())
	if scale > 0 {
		out.WriteByte('.')
		out.WriteString(fracStr)
	}
	return out.String()
}

func formatAmt(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZ9.99")
}
func formatBal(v decimal.Decimal) string {
	return formatEdited(v, "-Z,ZZZ,ZZ9.99")
}
func formatTot(v decimal.Decimal) string {
	return formatEdited(v, "-ZZZ,ZZZ,ZZ9.99")
}

func formatSkipped(v int64) string {
	m := v % 100
	if m < 0 {
		m = -m
		// COBOL unsigned? keep positive digits
	}
	s := fmt.Sprintf("%02d", m)
	if len(s) > 2 {
		s = s[len(s)-2:]
	}
	return s
}

func display(s string) {
	os.Stdout.WriteString(s + "\n")
}

func MAINPARA() {
	// OPEN INPUT LEDGER-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty?
		// COBOL OPEN would fail; report to stderr
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	sc := bufio.NewScanner(f)
	// allow long lines, preserve spaces: default split works
	inputLines = nil
	for sc.Scan() {
		inputLines = append(inputLines, sc.Text())
	}
	f.Close()
	inputIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if !isFirstRecord() {
		ACCTBREAKPARA()
		BRANCHBREAKPARA()
	}
	// CLOSE already done
	GRANDPARA()
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	curRec = parseLine(line)
}

func PROCESSPARA() {
	if isFirstRecord() {
		WsPrevBranch = curRec.BrBranch
		WsPrevAcct = curRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if curRec.BrBranch != WsPrevBranch {
			ACCTBREAKPARA()
			BRANCHBREAKPARA()
			WsPrevBranch = curRec.BrBranch
			WsPrevAcct = curRec.BrAcct
		} else {
			if curRec.BrAcct != WsPrevAcct {
				ACCTBREAKPARA()
				WsPrevAcct = curRec.BrAcct
			}
		}
	}
	POSTPARA()
	READPARA()
}

func POSTPARA() {
	WsAmtEd = formatAmt(curRec.BrAmt)
	switch curRec.BrType {
	case "D":
		WsBal = storeBal(WsBal.Add(curRec.BrAmt))
		display(curRec.BrAcct + " D " + WsAmtEd)
	case "C":
		WsBal = storeBal(WsBal.Sub(curRec.BrAmt))
		display(curRec.BrAcct + " C " + WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		display(curRec.BrAcct + " ? SKIPPED")
	}
}

func ACCTBREAKPARA() {
	WsBalEd = formatBal(WsBal)
	display("  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd)
	WsBranchTot = storeTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.NewFromInt(0)
}

func BRANCHBREAKPARA() {
	WsTotEd = formatTot(WsBranchTot)
	display(" BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd)
	WsGrandTot = storeTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.NewFromInt(0)
}

func GRANDPARA() {
	WsTotEd = formatTot(WsGrandTot)
	display("GRAND TOTAL:" + WsTotEd)
	display("SKIPPED: " + formatSkipped(WsSkipped))
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = strings.Repeat(" ", 2)
	WsPrevAcct = strings.Repeat(" ", 4)
	WsBal = decimal.NewFromInt(0)
	WsBranchTot = decimal.NewFromInt(0)
	WsGrandTot = decimal.NewFromInt(0)
	WsSkipped = 0
	MAINPARA()
}
